select * from (
SELECT p.close FROM prices p WHERE p.symbol = 'AAPL' AND p.date = DATE '2026-11-16'
) as limited limit 1000

select * from (
SELECT MAX(p.close) AS highest_close FROM prices p WHERE p.symbol = 'NVDA'
) as limited limit 1000

select * from (
SELECT COUNT(*) AS trading_days FROM prices p WHERE p.symbol = 'MSFT' AND p.date >= DATE '2024-01-01' AND p.date <= DATE '2024-12-31'
) as limited limit 1000

select * from (
SELECT COUNT(*) AS total_8k_2025 FROM filings f WHERE f.form_type = '8-K' AND f.filed_at >= DATE '2025-01-01' AND f.filed_at <= DATE '2025-12-31'
) as limited limit 1000
